snippet_css:
:root{
  --bg: #1D2B53;
  --fg: #FFF1E8;
  --muted: #C2C3C7;
  --surface: #243463;
  --border: #5F574F;
  --accent: #FFEC27;
  --accent-fg: #1D2B53;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: 4px 4px 0 #0E1730;
  --btn-shadow: 4px 4px 0 #FF004D;
  --art-bg: linear-gradient(180deg,#29ADFF 0 52%,#1D2B53 52%);
  --media-bg: repeating-linear-gradient(0deg,#008751 0 12px,#00E436 12px 24px);
  --cta-bg: #243463;
  --input-bg: #16203D;
  --ok: #00E436;
  --warn: #FF004D;
  --font-display: 'Press Start 2P','Noto Sans TC',monospace;
  --font-body: 'VT323','Noto Sans TC',sans-serif;
  --font-mono: 'VT323',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
